BEGIN;
SET LOCAL lock_timeout='5s'; SET LOCAL statement_timeout='60s';
LOCK TABLE public.questions IN SHARE ROW EXCLUSIVE MODE;
CREATE TEMP TABLE swsi_before ON COMMIT DROP AS SELECT id, to_jsonb(q) AS row FROM public.questions q;
CREATE TEMP TABLE swsi_batch(id text primary key, status text, note text, url text) ON COMMIT DROP;
INSERT INTO swsi_batch VALUES ('SP104-1-26','verified_current',$swsi$考試時點法規核對（逐條人工核對）：本題考試日 2015-02-07。本題考社會工作師法第10條（不得發給執業執照之情事）。2018-12-19 修正將「罹患精神疾病…經專科醫師認定不能執行業務」改為「有客觀事實認不能執行業務，經小組認定」；2023-06-09 修正將犯罪事由移列第7條（不得充任社會工作師），選項(A)(B)(C)情形仍不得執業，選項(D)「出境歇業未報備」仍非法定事由。官方答案依現行條文仍正確。依據：法務部全國法規資料庫現行條文、法規沿革及歷史條文（2026-11-25 查核）。$swsi$,'https://law.moj.gov.tw/LawClass/LawAll.aspx?pcode=D0050125'),('SP104-1-27','verified_current',$swsi$考試時點法規核對（逐條人工核對）：本題考社會工作師法第33條（地方社會工作師公會成立人數），最後修正公布日：第33條 2008-01-16，本題考試日 2015-02-07 之後未再修正，考試時條文與現行條文相同，官方答案依現行條文仍正確。依據：法務部全國法規資料庫現行條文、法規沿革及歷史條文（2026-11-25 查核）。$swsi$,'https://law.moj.gov.tw/LawClass/LawAll.aspx?pcode=D0050125'),('SP104-2-27','verified_current',$swsi$考試時點法規核對（逐條人工核對）：本題考社會工作師法第12條（社會工作師業務範圍），最後修正公布日：第12條 2008-01-16，本題考試日 2015-07-25 之後未再修正，考試時條文與現行條文相同，官方答案依現行條文仍正確。依據：法務部全國法規資料庫現行條文、法規沿革及歷史條文（2026-11-25 查核）。$swsi$,'https://law.moj.gov.tw/LawClass/LawAll.aspx?pcode=D0050125'),('SP104-2-40','verified_current',$swsi$考試時點法規核對（逐條人工核對）：本題考社會工作師法第16條、第18條、第21條（執業處所、繼續教育年限與事務所設立資格），最後修正公布日：第16條 2008-01-16、第18條 2008-01-16、第21條 2008-01-16，本題考試日 2015-07-25 之後未再修正，考試時條文與現行條文相同，官方答案依現行條文仍正確。依據：法務部全國法規資料庫現行條文、法規沿革及歷史條文（2026-11-25 查核）。$swsi$,'https://law.moj.gov.tw/LawClass/LawAll.aspx?pcode=D0050125'),('SP105-2-40','verified_current',$swsi$考試時點法規核對（逐條人工核對）：本題考社會工作師法第16條、第18條、第21條、第28條（紀錄保存、繼續教育、事務所設立及停歇業報備期限），最後修正公布日：第16條 2008-01-16、第18條 2008-01-16、第21條 2008-01-16、第28條 2008-01-16，本題考試日 2016-07-23 之後未再修正，考試時條文與現行條文相同，官方答案依現行條文仍正確。依據：法務部全國法規資料庫現行條文、法規沿革及歷史條文（2026-11-25 查核）。$swsi$,'https://law.moj.gov.tw/LawClass/LawAll.aspx?pcode=D0050125'),('SP106-2-19','verified_current',$swsi$考試時點法規核對（逐條人工核對）：本題考社會工作師法第9條、第16條、第25條（執業登記、紀錄保存與收費標準），最後修正公布日：第9條 2008-01-16、第16條 2008-01-16、第25條 2008-01-16，本題考試日 2017-07-29 之後未再修正，考試時條文與現行條文相同，官方答案依現行條文仍正確。依據：法務部全國法規資料庫現行條文、法規沿革及歷史條文（2026-11-25 查核）。$swsi$,'https://law.moj.gov.tw/LawClass/LawAll.aspx?pcode=D0050125'),('SP106-2-27','changed',$swsi$考試時點法規核對（逐條人工核對）：本題考試日 2017-07-29。本題考社會工作師法第49條。考試時規定「外國人及華僑得依中華民國法律，應社會工作師考試」（官方答案D）；2020-01-15 修正刪除「華僑」，現行條文為「外國人得依中華民國法律，應社會工作師考試」，選項(D)用語已與現行條文不同。本題官方答案依考試時條文判定；作答時請以現行條文為準。依據：法務部全國法規資料庫現行條文、法規沿革及歷史條文（2026-11-25 查核）。$swsi$,'https://law.moj.gov.tw/LawClass/LawAll.aspx?pcode=D0050125'),('SP106-2-34','verified_current',$swsi$考試時點法規核對（逐條人工核對）：本題考社會工作師法第21條（事務所設立須執行業務五年以上），最後修正公布日：第21條 2008-01-16，本題考試日 2017-07-29 之後未再修正，考試時條文與現行條文相同，官方答案依現行條文仍正確。依據：法務部全國法規資料庫現行條文、法規沿革及歷史條文（2026-11-25 查核）。$swsi$,'https://law.moj.gov.tw/LawClass/LawAll.aspx?pcode=D0050125'),('SP106-2-36','verified_current',$swsi$考試時點法規核對（逐條人工核對）：本題考社會工作師法第33條（地方社會工作師公會成立人數），最後修正公布日：第33條 2008-01-16，本題考試日 2017-07-29 之後未再修正，考試時條文與現行條文相同，官方答案依現行條文仍正確。依據：法務部全國法規資料庫現行條文、法規沿革及歷史條文（2026-11-25 查核）。$swsi$,'https://law.moj.gov.tw/LawClass/LawAll.aspx?pcode=D0050125'),('SP107-2-09','verified_current',$swsi$考試時點法規核對（逐條人工核對）：本題考社會工作師法第18條（繼續教育與執業執照每六年更新），最後修正公布日：第18條 2008-01-16，本題考試日 2018-07-28 之後未再修正，考試時條文與現行條文相同，官方答案依現行條文仍正確。依據：法務部全國法規資料庫現行條文、法規沿革及歷史條文（2026-11-25 查核）。$swsi$,'https://law.moj.gov.tw/LawClass/LawAll.aspx?pcode=D0050125'),('SP107-2-32','verified_current',$swsi$考試時點法規核對（逐條人工核對）：本題考試日 2018-07-28。本題考社會工作師法第15條（保密）、第16條（紀錄保存七年、執業處所）、第19條。2023-06-09 修正第19條為執行第12條第1款至第3款業務時，有受妨礙或身體、精神遭受不法侵害之虞者，得請求警察機關提供必要之協助，選項(D)意旨未變。官方答案依現行條文仍正確。依據：法務部全國法規資料庫現行條文、法規沿革及歷史條文（2026-11-25 查核）。$swsi$,'https://law.moj.gov.tw/LawClass/LawAll.aspx?pcode=D0050125'),('SP108-1-26','verified_current',$swsi$考試時點法規核對（逐條人工核對）：本題考社會工作師法第33條（地方社會工作師公會成立人數），最後修正公布日：第33條 2008-01-16，本題考試日 2019-01-19 之後未再修正，考試時條文與現行條文相同，官方答案依現行條文仍正確。依據：法務部全國法規資料庫現行條文、法規沿革及歷史條文（2026-11-25 查核）。$swsi$,'https://law.moj.gov.tw/LawClass/LawAll.aspx?pcode=D0050125'),('SP108-1-27','verified_current',$swsi$考試時點法規核對（逐條人工核對）：本題考社會工作師法第1條（立法目的），最後修正公布日：第1條 2008-01-16，本題考試日 2019-01-19 之後未再修正，考試時條文與現行條文相同，官方答案依現行條文仍正確。依據：法務部全國法規資料庫現行條文、法規沿革及歷史條文（2026-11-25 查核）。$swsi$,'https://law.moj.gov.tw/LawClass/LawAll.aspx?pcode=D0050125'),('SP108-2-31','verified_current',$swsi$考試時點法規核對（逐條人工核對）：本題考社會工作師法第46條（事務所罰鍰以負責社會工作師為處罰對象），最後修正公布日：第46條 2008-01-16，